SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(240);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");R<T>:=PolynomialRing(Rationals());K<a>:=NumberField(R![2,2,-1,-2,-1,1]);b:=Evaluate(R![1032,-239,-222,-759,419],a);c:=Evaluate(R![42,-11,-8,-31,17],a);E:=EllipticCurve([1-c,-b,-b,0,0]);P:=E![0,0];assert Order(P) eq 28;T2:=14*P;RK<X>:=PolynomialRing(K);h:=DivisionPolynomial(E,2) div (X-T2[1]);assert Degree(h) eq 2 and IsIrreducible(h);L<r>:=NumberField(h);EL:=ChangeRing(E,L);PL:=EL!P;ai:=aInvariants(EL);S:=EL![r,-(ai[1]*r+ai[3])/2];assert Order(S) eq 2 and S ne 14*PL;out:=[* *];
